// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    Recorder rec;

    function setUp() public { c = new Reentrance(); rec = new Recorder(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1000 ether);
        vm.deal(address(rec), amount);
        vm.prank(address(rec));
        c.addToBalance{value: amount}();
        uint256 balBefore = c.getBalance(address(rec));

        vm.prank(address(rec));
        c.withdrawBalance();

        assertTrue(rec.recorded() == balBefore && balBefore > 0, "withdraw must send the full balance out");
    }
}

contract Recorder {
    uint256 public recorded;
    receive() external payable { recorded += msg.value; }
}
